-- Original practice instructions. Idempotent append, retaining quizzes and previous material.
with authored(lesson_no,section) as (values
  (0, $curriculum${"heading": "Pierwsze zadanie w Eksploratorze", "text": "Otwórz warsztat Windows 11. Na pasku poleceń wybierz Nowy → Folder i wpisz Odbiory. Zaznacz Notatka.txt, wybierz Kopiuj, otwórz Odbiory i wklej plik. Wróć strzałką Wstecz. Porównaj oba foldery i sprawdź, gdzie jest oryginał. Na prawdziwym komputerze Win+E uruchamia Eksplorator, a pozostałe kroki wykonujesz w jego oknie."}$curriculum$::jsonb),
  (3, $curriculum${"heading": "Pasek poleceń, adres i lista plików", "text": "Eksplorator Windows 11 pokazuje foldery w panelu nawigacji, ścieżkę u góry i zawartość w głównej części okna. Na pasku poleceń są m.in. Nowy, Wytnij, Kopiuj, Wklej, Zmień nazwę i Usuń. Część przycisków staje się dostępna po zaznaczeniu pliku. W warsztacie zaznacz Notatka.txt, sprawdź przyciski, następnie wybierz Otwórz wybrany element i odczytaj treść."}$curriculum$::jsonb),
  (4, $curriculum${"heading": "Ścieżka folderu i rozszerzenie pliku", "text": "Adres „Dokumenty\\\\Projekty” w warsztacie oznacza folder Projekty wewnątrz Dokumentów. Nazwa „Plan.txt” wskazuje plik tekstowy. W Windows przejdź do Widok → Pokaż → Rozszerzenia nazw plików, aby wyświetlić końcówki nazw. Porównaj nazwę Notatka przed i po przełączeniu widoku. Zmiana końcówki w nazwie pliku pozostawia jego dotychczasowy format danych."}$curriculum$::jsonb),
  (5, $curriculum${"heading": "Ctrl, Alt, Shift i klawisz Windows", "text": "Ctrl łączy się często z operacją na danych, jak Ctrl+C. Alt pojawia się w poleceniach nawigacji, np. Alt+strzałka w górę prowadzi do folderu nadrzędnego. Shift zmienia zachowanie innych klawiszy. Ctrl+Shift+N tworzy nowy folder w Eksploratorze. Win+E uruchamia Eksplorator z pulpitu Windows. Przeglądarka może oddać część klawiszy systemowi, więc w warsztacie najpierw kliknij jego obszar albo użyj ekranowych przycisków."}$curriculum$::jsonb),
  (9, $curriculum${"heading": "Utwórz folder i popraw jego nazwę", "text": "Otwórz Dokumenty. Wybierz Nowy → Folder lub Ctrl+Shift+N i utwórz „Projekt listopad”. Zaznacz folder i użyj F2, żeby zmienić nazwę na „Projekt listopad 2026”. Zatwierdź Enterem i otwórz folder, aby sprawdzić ścieżkę. Jeśli w docelowym folderze istnieje już ta sama nazwa, wybierz inną. Wspólna konwencja nazw ułatwia wyszukiwanie, np. nazwa projektu plus data."}$curriculum$::jsonb),
  (14, $curriculum${"heading": "Trzy sposoby poruszania się po folderach", "text": "Alt+strzałka w lewo cofa do poprzedniej lokalizacji w historii, Alt+strzałka w prawo idzie do przodu w historii, a Alt+strzałka w górę przechodzi do folderu nadrzędnego. To różne działania. Otwórz Projekty z Dokumentów, potem wróć i przejdź do innego folderu. Użyj Wstecz, a później W górę w jednym z podfolderów. Porównaj wynik z adresem na pasku."}$curriculum$::jsonb),
  (15, $curriculum${"heading": "Kopia a przeniesienie pliku", "text": "Zaznacz Notatka.txt, użyj Ctrl+C, przejdź do Projekty i użyj Ctrl+V. Kopia jest w Projekty, a oryginał w Dokumenty. Przy Ctrl+X i Ctrl+V ten sam element zmienia folder po wklejeniu. Przed działaniem potwierdź nazwę i folder docelowy. W warsztacie możesz sprawdzić oba katalogi, a nieudaną operację cofnąć. Uważaj szczególnie, gdy folder docelowy zawiera dokument o tej samej nazwie."}$curriculum$::jsonb),
  (16, $curriculum${"heading": "Pasek adresu z klawiatury", "text": "Ctrl+L lub Alt+D ustawia kursor w pasku adresu Eksploratora. Wpisz ścieżkę i naciśnij Enter. W warsztacie użyj Dokumenty\\\\Projekty. Następnie przejdź poziom wyżej strzałką W górę. Gdy adres prowadzi gdzie indziej, sprawdź folder nadrzędny i nazwę podfolderu. Zanim zmienisz nazwę albo usuniesz plik, przeczytaj bieżącą ścieżkę. Tak znajdziesz właściwą kopię."}$curriculum$::jsonb),
  (18, $curriculum${"heading": "Odzyskaj plik po pomyłce", "text": "W warsztacie utwórz folder próbny, usuń go i od razu użyj Cofnij zmianę. Sprawdź, czy element wrócił na listę. W Windows Ctrl+Z w Eksploratorze może odwrócić ostatnią obsługiwaną operację. Po zwykłym usunięciu z lokalnego folderu możesz też sprawdzić Kosz, o ile element tam trafił. Zależnie od urządzenia, lokalizacji i sposobu usuwania dostępne mechanizmy odzyskiwania się różnią."}$curriculum$::jsonb),
  (20, $curriculum${"heading": "Nazwij pliki tak, żeby wersję rozpoznać od razu", "text": "Ustal porządek „projekt-temat-R01”, „projekt-temat-R02” lub dodawaj datę w układzie rok–miesiąc–dzień. Użyj F2 do zmiany nazwy kopii roboczej. Sprawdź rozszerzenie i otwórz plik, żeby porównać rzeczywistą zawartość. Folder Wydane może zawierać tylko zatwierdzone pliki, a Robocze wersje edytowane. Dzięki temu nowa osoba potrafi wskazać właściwy dokument bez zgadywania."}$curriculum$::jsonb),
  (24, $curriculum${"heading": "Pokaż rozszerzenia i przeczytaj pełną nazwę", "text": "W Eksploratorze wybierz Widok → Pokaż → Rozszerzenia nazw plików. Na przykład „instrukcja.pdf” oraz „instrukcja.pdf.exe” mają różne ostatnie rozszerzenia. Przed otwarciem pliku przeczytaj jego pełną nazwę i sprawdź, od kogo pochodzi. Gdy plik należy przekonwertować, skorzystaj z zapisu lub eksportu w odpowiednim programie. Zmiana nazwy sama w sobie zachowuje dane wewnątrz pliku."}$curriculum$::jsonb),
  (29, $curriculum${"heading": "Samodzielna organizacja dokumentów", "text": "Załóż folder projektu i dwa podfoldery: Robocze oraz Do wysłania. Skopiuj Notatka.txt do Robocze, zmień nazwę kopii tak, by wskazywała temat, a później przenieś kopię do Do wysłania. Użyj paska adresu, żeby sprawdzić obie lokalizacje. Otwórz plik w celu kontroli zawartości i wróć do Dokumentów, aby potwierdzić, że oryginał jest dostępny."}$curriculum$::jsonb)
)
update public.ta_lessons lesson
set material=jsonb_set(lesson.material,'{sections}',
    coalesce(lesson.material->'sections','[]'::jsonb)||jsonb_build_array(authored.section),true),
    updated_at=now()
from authored
where lesson.course_slug='windows-skroty' and lesson.lesson_no=authored.lesson_no
and not exists (
  select 1 from jsonb_array_elements(coalesce(lesson.material->'sections','[]'::jsonb)) as existing(section)
  where existing.section->>'heading'=authored.section->>'heading'
)
returning lesson.lesson_no,authored.section->>'heading' as added_section;
